{
  "story": "The client sends SYN, and the server replies with SYN-ACK. The server still waits until the client's final ACK arrives. Compare endpoint states after each delivered segment. Assume reliable delivery, no payload, and no wraparound. Initial sequence numbers are fixed and shown at the start.",
  "aha": {
    "stateId": "ack-received",
    "observation": "The final ACK confirms receipt of the server's SYN, letting the server join the client in ESTABLISHED."
  },
  "layout": {
    "preset": "stepper-states/protocol",
    "width": 640
  },
  "parts": [
    {
      "id": "handshake-rail",
      "kind": "step-rail",
      "presentation": "Use the approved card shell, with story and navigation instructions above the experiment. Keep progress on this rail. Steps represent states, not time.",
      "bind": {
        "active": "state.id",
        "items": "variant.states"
      }
    },
    {
      "id": "connection-picture",
      "kind": "fixed-picture",
      "presentation": "Use the canonical protocol arrangement: Client left, Server right, and three fixed message lanes between them. Order lanes SYN, SYN-ACK, then ACK. Route each link through its matching message region. Keep labels visible and mute inactive regions. Highlight bound active regions without movement.",
      "bind": {
        "active": "state.active",
        "links": "variant.links",
        "regions": "variant.regions"
      }
    },
    {
      "id": "delivery-callout",
      "kind": "active-callout",
      "presentation": "Anchor beside the target region without covering labels. Identify the relevant actor or message here; report numeric values only in readouts.",
      "bind": {
        "target": "state.calloutRegion",
        "text": "state.sentence",
        "reason": "state.why"
      }
    },
    {
      "id": "connection-readouts",
      "kind": "value-readout",
      "presentation": "Place endpoint states together, followed by sequence fields. Reserve the bottom line for the endpoint counter and connection status. Derive the counter from endpoint states. Values describe the latest delivered segment, except initial sequence numbers shown before delivery. Sequence values are exact, dimensionless integers without rounding. An acknowledgment names the next sequence number expected from the peer.",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "handshake-step",
      "kind": "index",
      "items": "variant.states",
      "label": "Handshake step",
      "presentation": "Navigation budget: one index control. Parameter-control budget: zero. Default: first state. Bounds: first through fourth state. Increment: one state. Use Previous and Next, retaining their names when disabled at boundaries. Each activation updates the picture, explanation, and readouts. Every state persists until the learner acts; never autoplay. Reference captures must show ack-received. Provide accessible button names, visible focus, and keyboard activation."
    },
    {
      "id": "reset",
      "kind": "reset",
      "label": "Reset",
      "presentation": "Restore the first state and all fixed defaults. Provide the accessible name Reset, visible focus, and keyboard activation."
    }
  ],
  "data": {
    "variants": [
      {
        "label": "TCP connection opening",
        "regions": [
          {
            "id": "client",
            "label": "Client",
            "actors": [
              "Active opener"
            ]
          },
          {
            "id": "server",
            "label": "Server",
            "actors": [
              "Listening endpoint"
            ]
          },
          {
            "id": "syn",
            "label": "SYN",
            "values": [
              "Client → Server"
            ]
          },
          {
            "id": "syn-ack",
            "label": "SYN-ACK",
            "values": [
              "Server → Client"
            ]
          },
          {
            "id": "ack",
            "label": "ACK",
            "values": [
              "Client → Server"
            ]
          }
        ],
        "links": [
          {
            "from": "client",
            "to": "syn",
            "label": ""
          },
          {
            "from": "syn",
            "to": "server",
            "label": ""
          },
          {
            "from": "server",
            "to": "syn-ack",
            "label": ""
          },
          {
            "from": "syn-ack",
            "to": "client",
            "label": ""
          },
          {
            "from": "client",
            "to": "ack",
            "label": ""
          },
          {
            "from": "ack",
            "to": "server",
            "label": ""
          }
        ],
        "states": [
          {
            "id": "before-opening",
            "label": "Before opening",
            "short": "Start",
            "sentence": "Server is listening; Client has not opened a connection.",
            "why": "The fixed initial sequence numbers identify where each endpoint's sequence space begins.",
            "active": [
              "server"
            ],
            "calloutRegion": "server",
            "readouts": [
              {
                "id": "client-state",
                "label": "Client state",
                "value": "CLOSED"
              },
              {
                "id": "server-state",
                "label": "Server state",
                "value": "LISTEN"
              },
              {
                "id": "client-initial-sequence",
                "label": "Client initial sequence",
                "value": "1000"
              },
              {
                "id": "server-initial-sequence",
                "label": "Server initial sequence",
                "value": "5000"
              },
              {
                "id": "connection-status",
                "label": "Established endpoints",
                "value": "0 of 2 · Connection not ready"
              }
            ]
          },
          {
            "id": "syn-received",
            "label": "SYN received",
            "short": "SYN",
            "sentence": "Server receives Client's SYN and prepares its SYN-ACK response.",
            "why": "SYN introduces Client's initial sequence number and consumes one sequence number, even without payload.",
            "active": [
              "syn",
              "server"
            ],
            "calloutRegion": "syn",
            "readouts": [
              {
                "id": "client-state",
                "label": "Client state",
                "value": "SYN-SENT"
              },
              {
                "id": "server-state",
                "label": "Server state",
                "value": "SYN-RECEIVED"
              },
              {
                "id": "delivered-sequence",
                "label": "Delivered sequence",
                "value": "1000"
              },
              {
                "id": "delivered-acknowledgment",
                "label": "Delivered acknowledgment",
                "value": "Not valid: ACK flag clear"
              },
              {
                "id": "connection-status",
                "label": "Established endpoints",
                "value": "0 of 2 · Connection not ready"
              }
            ]
          },
          {
            "id": "syn-ack-received",
            "label": "SYN-ACK received",
            "short": "SYN-ACK",
            "sentence": "Client receives SYN-ACK and enters ESTABLISHED; Server still waits for the final ACK.",
            "why": "The acknowledgment equals Client's initial sequence number plus one; Server still needs acknowledgment of its own SYN.",
            "active": [
              "syn-ack",
              "client"
            ],
            "calloutRegion": "syn-ack",
            "readouts": [
              {
                "id": "client-state",
                "label": "Client state",
                "value": "ESTABLISHED"
              },
              {
                "id": "server-state",
                "label": "Server state",
                "value": "SYN-RECEIVED"
              },
              {
                "id": "delivered-sequence",
                "label": "Delivered sequence",
                "value": "5000"
              },
              {
                "id": "delivered-acknowledgment",
                "label": "Delivered acknowledgment",
                "value": "1001"
              },
              {
                "id": "connection-status",
                "label": "Established endpoints",
                "value": "1 of 2 · Server still waiting"
              }
            ]
          },
          {
            "id": "ack-received",
            "label": "Final ACK received",
            "short": "ACK",
            "sentence": "Server receives the final ACK; Client and Server are now both ESTABLISHED.",
            "why": "The acknowledgment equals Server's initial sequence number plus one, confirming receipt of its SYN.",
            "active": [
              "ack",
              "client",
              "server"
            ],
            "calloutRegion": "ack",
            "readouts": [
              {
                "id": "client-state",
                "label": "Client state",
                "value": "ESTABLISHED"
              },
              {
                "id": "server-state",
                "label": "Server state",
                "value": "ESTABLISHED"
              },
              {
                "id": "delivered-sequence",
                "label": "Delivered sequence",
                "value": "1001"
              },
              {
                "id": "delivered-acknowledgment",
                "label": "Delivered acknowledgment",
                "value": "5001"
              },
              {
                "id": "connection-status",
                "label": "Established endpoints",
                "value": "2 of 2 · Connection established"
              }
            ]
          }
        ]
      }
    ]
  }
}
